text:
{
  "tasks": [
    {
      "task_id": "T1",
      "title": "上海与杭州薪资元平均值对比及排名",
      "business_question": "在只看上海与杭州的前提下，比较两地的薪资元平均值，并按薪资元平均值降序排名。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心业务问题（比较两地薪资均值）并支持决策（排名），且直接关联所有核心需求 C01-C04。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "in",
                "value": [
                  "上海",
                  "杭州"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "salary_avg"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "salary_avg",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
